// Small copies of the real documents, inlined so a thumbnail paints with the first render instead of waiting on
// a request (the shelf never flashes blank, and the film's crops of it never catch a half-loaded page).
// Each is its picture in public/demo/library/ resized to 360 px wide (Lanczos) and saved as WebP at quality 86.
// Thumbnails use them as their picture; the viewer shows one under the full-size file while that loads.
import { assetUrl } from './assets';

const THUMBS = {
  'demo/library/st2187-business-analytics-cover.png': 'data:image/webp;base64,',
  'demo/library/common-continuous-distributions.png': 'data:image/webp;base64,',
  'demo/library/summation-notation.png': 'data:image/webp;base64,',
  'demo/library/mn1178-chapter-7.png': 'data:image/webp;base64,',
};

/** The inline thumbnail of a file's picture (the full-size file if there isn't one). */
export const thumbSrc = (image) => THUMBS[image.src] || assetUrl(image.src);
